cd /data/worktrees/sr2/sr2-142 && .venv/bin/python - <<'PY'
p = "tests/continuity/test_consolidation.py"
s = open(p).read()
old = '''        caches = [
            value
            for value in vars(consolidators[0]).values()
            if isinstance(value, cache_class)
        ]
        assert len(caches) == 1, (
            "a consolidator must hold exactly one projection cache of its "
            f"own; it holds {len(caches)}"
        )
        assert not any(
            isinstance(value, cache_class)
            for value in vars(consolidators[1]).values()
        ), "consolidators[1] must not share consolidators[0]'s cache object"'''
new = '''        def caches_of(instance: object) -> list:
            return [
                value
                for value in vars(instance).values()
                if isinstance(value, cache_class)
            ]

        caches = caches_of(consolidators[0])
        assert len(caches) == 1, (
            "a consolidator must hold exactly one projection cache of its "
            f"own; it holds {len(caches)}"
        )
        assert len(caches_of(consolidators[1])) == 1
        assert caches[0] is not caches_of(consolidators[1])[0], (
            "two consolidators share one projection cache object — that is "
            "the module-global leak under another name"
        )'''
assert old in s
open(p, "w").write(s.replace(old, new))
PY
